def transform(grid):
    tile=[row[:5] for row in grid[:5]]
    out=[row[:] for row in tile]
    for r in range(5):
        for c in range(5):
            v=tile[r][c]
            if v in (0,6):
                out[r][c]=1
            elif v==4:
                neighbors=[tile[rr][cc] for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=rr<5 and 0<=cc<5]
                if any(x!=8 for x in neighbors): out[r][c]=1
    return out
